from typing import List, Tuple

def count_intersecting_pairs(N: int, intervals: List[Tuple[int, int]]) -> int:
    intersecting_pairs = 0

    for i in range(N):
        l_i, r_i = intervals[i]
        for j in range(i + 1, N):
            l_j, r_j = intervals[j]
            if l_i <= r_j and l_j <= r_i:
                intersecting_pairs += 1

    return intersecting_pairs
